192	        if (permStatus.receive !== 'granted') {
193	          toast({ title: "Notification permission denied", description: "Please enable in iOS Settings > TaptPay", variant: "destructive" });
194	          setPushLoading(false);
195	          return;
196	        }
197	        await new Promise<void>((resolve, reject) => {
198	          const timer = setTimeout(() => reject(new Error('Registration timed out')), 15000);
199	          const regHandle = PushNotifications.addListener('registration', async (token) => {
200	            clearTimeout(timer);
201	            regHandle.then(h => h.remove());
202	            errHandle.then(h => h.remove());
203	            try {
204	              const authToken = localStorage.getItem("authToken");
205	              const resp = await fetch('/api/push/native-subscribe', {
206	                method: 'POST',
207	                headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${authToken}` },
