310	  function urlBase64ToUint8Array(base64String: string): Uint8Array {
311	    const padding = '='.repeat((4 - base64String.length % 4) % 4);
312	    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
313	    const rawData = window.atob(base64);
314	    const outputArray = new Uint8Array(rawData.length);
315	    for (let i = 0; i < rawData.length; ++i) {
316	      outputArray[i] = rawData.charCodeAt(i);
317	    }
318	    return outputArray;
319	  }
