import { useState, useMemo } from "react";
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { useLocation } from "wouter";
import { useToast } from "@/hooks/use-toast";
import { getCurrentMerchantId } from "@/lib/auth";
import {
  type LucideIcon,
  Search, Plus, Package, Trash2, X, ChevronDown, ChevronUp,
  ArrowUpAZ, ArrowDownAZ, ArrowUp01, ArrowDown01,
} from "lucide-react";
import { Sheet, SheetContent } from "@/components/ui/sheet";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Button } from "@/components/ui/button";

interface VariationOption {
  label: string;
  priceModifier: number;
}
interface VariationGroup {
  name: string;
  options: VariationOption[];
}
interface StockItem {
  id: number;
  name: string;
  cost: string | number;
  description?: string;
  emoji?: string | null;
  variations?: VariationGroup[] | null;
}

type SortKey = "az" | "za" | "price-asc" | "price-desc";

const EMOJI_OPTIONS = [
  "☕","🍕","🍔","🍟","🌮","🍣","🍜","🥗","🍰","🧁",
  "🍺","🥤","🍷","🧃","🥛","🍫","🍬","🍭","🎁","🛍️",
  "👕","👗","👟","🎮","📱","💻","⌚","💍","🌸","🎵",
  "🏋️","🚗","🏠","🌿","🐾","✂️","🔑","📦","🧴","💊",
];

function EmojiPicker({ value, onChange }: { value: string; onChange: (e: string) => void }) {
  const [open, setOpen] = useState(false);
  return (
    <div>
      <button
        type="button"
        onClick={() => setOpen((o) => !o)}
        className="flex items-center gap-2 text-sm text-gray-700 font-medium hover:text-[#0055FF] transition-colors"
      >
        <span className="text-xl leading-none">{value || "🏷️"}</span>
        <span>{value ? "Change icon" : "Add icon"}</span>
        <ChevronDown size={14} className={`text-gray-400 transition-transform ${open ? "rotate-180" : ""}`} />
      </button>

      {open && (
        <div className="mt-2 space-y-1">
          <div className="grid grid-cols-10 gap-1 bg-gray-50 rounded-xl p-2 border border-gray-200">
            {EMOJI_OPTIONS.map((e) => (
              <button
                key={e}
                type="button"
                onClick={() => { onChange(e); setOpen(false); }}
                className={`text-xl p-1 rounded-lg transition-colors hover:bg-blue-50 ${value === e ? "bg-blue-100 ring-2 ring-[#0055FF]" : ""}`}
              >
                {e}
              </button>
            ))}
          </div>
          {value && (
            <button
              type="button"
              onClick={() => { onChange(""); setOpen(false); }}
              className="text-xs text-gray-400 hover:text-gray-600"
            >
              Clear icon
            </button>
          )}
        </div>
      )}
    </div>
  );
}

function VariationsBuilder({
  variations,
  onChange,
}: {
  variations: VariationGroup[];
  onChange: (v: VariationGroup[]) => void;
}) {
  const addGroup = () =>
    onChange([...variations, { name: "", options: [{ label: "", priceModifier: 0 }] }]);

  const updateGroup = (gi: number, patch: Partial<VariationGroup>) =>
    onChange(variations.map((g, i) => (i === gi ? { ...g, ...patch } : g)));

  const removeGroup = (gi: number) => onChange(variations.filter((_, i) => i !== gi));

  const addOption = (gi: number) =>
    updateGroup(gi, { options: [...variations[gi].options, { label: "", priceModifier: 0 }] });

  const updateOption = (gi: number, oi: number, patch: Partial<VariationOption>) =>
    updateGroup(gi, {
      options: variations[gi].options.map((o, i) => (i === oi ? { ...o, ...patch } : o)),
    });

  const removeOption = (gi: number, oi: number) =>
    updateGroup(gi, { options: variations[gi].options.filter((_, i) => i !== oi) });

  return (
    <div className="space-y-3">
      <div className="flex items-center justify-between">
        <Label className="text-gray-700 font-medium text-sm">Variations</Label>
        <button
          type="button"
          onClick={addGroup}
          className="flex items-center gap-1 text-xs text-[#0055FF] font-medium hover:text-[#0044DD]"
        >
          <Plus size={13} /> Add group

return (
  <div className="min-h-screen pb-32" style={{ background: '#F4F4F4', fontFamily: "'Outfit', system-ui, sans-serif" }}>
    {/* Safe-area spacer */}
    <div style={{ height: 54 }} />

    {/* Tenant-profile-style navy header */}
    <div style={{ padding: '0 18px' }}>
      <div style={{ background: '#040D6D', borderRadius: 24, padding: '24px 26px 26px' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
          {/* Avatar */}
          <div style={{ width: 56, height: 56, borderRadius: 999, background: '#58ABFF', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
            <span style={{ fontWeight: 700, fontSize: 20, color: '#040D6D' }}>{initials}</span>
          </div>
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontWeight: 700, fontSize: 18, color: '#FFFFFF', letterSpacing: '-0.01em', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              {businessName}
            </div>
            <div style={{ fontWeight: 500, fontSize: 11, color: '#58ABFF', letterSpacing: '0.14em', textTransform: 'uppercase', marginTop: 3 }}>
              inventory
            </div>
          </div>
          {/* Item count badge */}
          <div style={{ display: 'inline-flex', alignItems: 'center', gap: 6, padding: '5px 11px', borderRadius: 10, background: 'rgba(88,171,255,0.18)', color: '#58ABFF', fontWeight: 600, fontSize: 11, letterSpacing: '0.06em', textTransform: 'uppercase', flexShrink: 0 }}>
            <span style={{ width: 6, height: 6, borderRadius: 999, background: '#58ABFF', flexShrink: 0 }} />
            {(stockItems as any[]).length} items
          </div>
        </div>
      </div>
    </div>

    {/* White rounded-top content area */}
    <div style={{ background: '#FFFFFF', borderRadius: '40px 40px 0 0', marginTop: 16 }}>
      <div className="max-w-3xl mx-auto px-4 sm:px-6 pt-6 sm:pt-8">

      {/* Search row with + button */}
      <div className="relative flex items-center gap-3 mb-4">
        <div className="relative flex-1">
          <input
            type="text"
            placeholder="Search products…"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-full bg-gray-50 border border-gray-200 rounded-full px-5 py-3 pl-11 text-gray-800 placeholder-gray-400 focus:outline-none focus:border-[#040D6D] text-sm"
            data-testid="input-search"
          />
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 text-gray-400" size={16} />
        </div>
        <button
          onClick={openAdd}
          data-testid="button-add-product"
          style={{ width: 44, height: 44, borderRadius: 999, background: '#040D6D', border: 'none', cursor: 'pointer', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0, boxShadow: '0 4px 14px rgba(4,13,109,0.3)' }}
        >
          <Plus size={20} color="#58ABFF" />
        </button>
      </div>

      {/* Sort toolbar */}
      <div className="flex items-center gap-1 mb-4 flex-wrap">
        {sortButtons.map(({ key, icon: Icon, label }) => (
          <button
            key={key}
            onClick={() => setSortKey(key)}
            className={`flex items-center gap-1 px-2.5 py-1.5 rounded-full text-xs font-medium transition-colors ${
              sortKey === key
                ? "bg-[#040D6D] text-white shadow-sm"
                : "bg-white text-gray-500 border border-gray-200 hover:border-[#040D6D] hover:text-[#040D6D]"
            }`}
          >
            <Icon size={12} />
            {label}
          </button>
        ))}
      </div>

      {/* Grid */}
      {isLoading ? (
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
          {Array.from({ length: 6 }).map((_, i) => (
            <div
              key={i}
              className="aspect-square rounded-2xl bg-white/40 animate-pulse"
            />
          ))}
        </div>
      ) : filteredAndSorted.length === 0 ? (
        <div className="text-center py-20 text-gray-400">
          <Package size={40} className="mx-auto mb-3 opacity-30" />
          <p className="text-sm">
            {searchQuery ? "No products match your search" : "No products yet — add your first!"}
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
          {filteredAndSorted.map((item) => {
            const hasVariations = item.variations && (item.variations as VariationGroup[]).length > 0;
            return (
              <button
                key={item.id}
                onClick={() => openEdit(item)}
                data-testid={`card-product-${item.id}`}
                className="group relative flex flex-col items-center justify-between text-left rounded-2xl overflow-hidden cursor-pointer transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] shadow-md hover:shadow-lg"
                style={{
                  background:
                    "linear-gradient(135deg, rgba(255,255,255,0.55) 0%, rgba(255,255,255,0.3) 100%)",
                  backdropFilter: "blur(16px)",
                  WebkitBackdropFilter: "blur(16px)",
                  border: "1px solid rgba(255,255,255,0.6)",
                }}
              >
                {/* Subtle inner glow */}

